    "id": "led_reacts_quickly",
    "requirement": "The LED changes state within 20 ms of a valid button press, so the user notices no delay."
  },
  {
    "id": "debounce_single_toggle",
    "requirement": "A single physical button press toggles the LED exactly once, even though the contacts bounce."
  },
  {
    "id": "serial_print_state",
    "requirement": "On every toggle, the board prints the new LED state, either ON or OFF, on its own line over Serial1 at 9600 baud."
  },
  {
    "id": "uses_serial1_not_usb",
    "requirement": "The code uses the Serial1 object (pins D0/D1) configured at 9600 baud for the state messages, not the USB Serial port."
  },
  {
    "id": "pin_d2_input_pullup",
    "requirement": "The code configures pin D2 as INPUT_PULLUP to read the button, since there is no external resistor."
  }
]
