<student_code untrusted="true">
=== no_debounce.ino ===
   1| // Toggle the LED with an interrupt on the button pin
   2| 
   3| volatile bool ledState = false;
   4| volatile bool changed = false;
   5| 
   6| void buttonPressed() {
   7|   ledState = !ledState;
   8|   digitalWrite(LED_BUILTIN, ledState);
   9|   changed = true;
  10| }
  11| 
  12| void setup() {
  13|   pinMode(2, INPUT_PULLUP);
  14|   pinMode(LED_BUILTIN, OUTPUT);
  15|   digitalWrite(LED_BUILTIN, LOW);
  16|   Serial1.begin(9600);
  17|   attachInterrupt(digitalPinToInterrupt(2), buttonPressed, FALLING);  // button pulls D2 low
  18| }
  19| 
  20| void loop() {
  21|   if (changed) {
  22|     changed = false;
  23|     Serial1.println(ledState ? "ON" : "OFF");
  24|   }
  25| }
</student_code>
